import{_ as i,l as n,o as e,c as l,v as r,p as s,x as t,d as C,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"奇偶与 CRC","description":"","frontmatter":{"title":"奇偶与 CRC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/parity-crc.md","filePath":"cs/parity-crc.md","lastUpdated":1789023840000}'),m={name:"cs/parity-crc.md"};function h(p,a,_,E,u,g){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="奇偶与-crc" tabindex="-1">奇偶与 CRC <a class="header-anchor" href="#奇偶与-crc" aria-label="Permalink to &quot;奇偶与 CRC&quot;">​</a></h1><div class="epigraph"><p>一位偶校验把码字推进偶数重量；CRC 把同一件事做成多项式除法的余数，突发翻转比随机单比特更常见时更有用。</p><footer>—— 据 Hamming, 1950；Peterson and Brown, Cyclic Codes for Error Detection, 1961；Knuth, The Art of Computer Programming, Vol. 2 整理</footer></div><p>上一课<a href="/cs/hamming-distance">汉明距离</a>钉死了 \\(d\\) 是度量，\\(d_{\\min}=2\\) 能检一位。本课不重证三角不等式，也不从「循环码理论」另起一篇综述。缺口是：距离还没有<strong>构造</strong>。一位奇偶怎么把 \\(d_{\\min}\\) 抬到 \\(2\\)；帧、磁盘上常用的 CRC 与奇偶是同一类运算的加长版，还是另一套几何。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>偶校验：添一位使全体比特模 \\(2\\) 和为 \\(0\\)，合法字落在超平面上，\\(d_{\\min}=2\\)，奇数位错必被发现，两位错看不见。缺口因此不是再定义距离，而是承认：这就是 \\(d=2\\) 的线性码，电路上是一排异或。突发错（连续 \\(k\\) 位）在链路上比独立翻转更常见，一位奇偶不够；把比特当成 \\(\\mathbb{F}_2\\) 上多项式的系数，除以固定生成元 \\(g(x)\\)，余数当校验，就是 CRC。</p><p>本课只钉检错。纠错定位（Hamming 码的综合征）上一课已点名，不在这里把矩阵写完。布尔代数还没有正式公理，异或先当模 \\(2\\) 加。</p><h3 id="crc-不是「已经纠正」" tabindex="-1">CRC 不是「已经纠正」 <a class="header-anchor" href="#crc-不是「已经纠正」" aria-label="Permalink to &quot;CRC 不是「已经纠正」&quot;">​</a></h3><p>余数不合则发现，合则<strong>可能</strong>漏检（错多项式是 \\(g\\) 的倍式）。把 CRC 通过当成数据正确，后课重传与 ECC DIMM 会少一步。纠正需要距离更大的码或重读。</p><p><span class="marginnote">Hamming 用奇偶作检错与 \\((7,4)\\) 的构件。Peterson–Brown 把循环冗余系统化。Knuth Vol. 2 的多项式算术给出 \\(\\mathbb{F}_2[x]\\) 上除法的同一套语言，本课不展开乘法实现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>奇偶：\\(p=\\bigoplus_i x_i\\)。CRC：把信息比特当多项式 \\(m(x)\\)，发送 \\(x^{r}m(x)-q(x)g(x)\\) 使 \\(g\\) 整除；接收端再除一次看余数是否为零。\\(r=\\deg g\\)。常见 \\(g\\) 是工程约定（如 CRC-32 多项式），本课不背表。能检的突发长度与 \\(g\\) 的性质有关，最坏 \\(d_{\\min}\\) 仍由码决定。</p>',11)),(e(),s(c,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20D2%5B%22d_min%20%3D%202%EF%BC%9A%E5%A5%87%E5%81%B6%22%5D%20--%3E%20XOR%5B%22%E6%A8%A1%202%20%E5%92%8C%22%5D%0A%20%20XOR%20--%3E%20POLY%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%E4%BD%99%E6%95%B0%EF%BC%9ACRC%22%5D%0A%20%20POLY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BC%82%E6%88%96%E6%88%90%E4%B8%BA%E5%B8%83%E5%B0%94%E8%BF%90%E7%AE%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[C(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>链路帧尾、以太网、压缩文件的 checksum 家族，多数是 CRC 或弱哈希；本栏网络课会再碰到帧，那时默认本课：CRC 管检，不管密码学完整性。后课<a href="/cs/boolean-algebra">布尔代数</a>把与、或、非写成公理，异或是导出运算；本课的校验已经在用它。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CRC 的线性反馈移位寄存器画法以外的时序细节——触发器还没有。也不把 MD5/SHA 当 CRC：加密哈希防主动攻击，CRC 防随机翻转。UTF-8 非法序列检测不是 CRC。</p><p>后课默认：一位奇偶 \\(d=2\\)；CRC 是多项式检错。组合功能从布尔公理开始写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>偶校验强制偶数重量，检奇数位错。</li><li>CRC 用 \\(\\mathbb{F}_2[x]\\) 余数检突发；通过不等于正确。</li><li>下一步需要的是对 \\(\\{0,1\\}\\) 的代数，不是更长的校验多项式。</li><li>出处：Hamming, 1950；Peterson and Brown, 1961；Knuth, TAOCP Vol. 2。</li></ul>',7))])}const B=i(m,[["render",h]]);export{R as __pageData,B as default};
